(pg_temp.sid('recipe:Protein overnight oats'),'Protein overnight oats','breakfast','Make it the night before and grab it in the morning.',5,540,43.2,67.4,12.7,array['60 g oats, dry','30 g whey protein powder','200 ml milk, semi-skimmed','80 g blueberries','10 g chia seeds']::text[],array['Stir oats, whey, chia and milk together in a jar.','Refrigerate overnight.','Top with blueberries before eating.']::text[],array['high protein','meal prep']::text[]),
(pg_temp.sid('recipe:Greek yogurt power bowl'),'Greek yogurt power bowl','breakfast','Fast, high protein and no cooking.',5,398,30.5,50.5,9.3,array['250 g Greek yogurt 0% fat','40 g granola','100 g strawberries','10 g honey']::text[],array['Spoon yogurt into a bowl.','Top with granola and sliced strawberries.','Drizzle with honey.']::text[],array['high protein','no cook']::text[]),
(pg_temp.sid('recipe:Veggie egg-white omelette'),'Veggie egg-white omelette','breakfast','Big volume, low calorie, plenty of protein.',12,357,39.6,24.1,11.1,array['200 g egg whites','50 g eggs, whole','50 g spinach','60 g mushrooms','50 g bell pepper','20 g feta','36 g wholemeal bread']::text[],array['Saute mushrooms and pepper in a non-stick pan.','Add spinach until wilted.','Pour in whisked egg whites and egg, cook until set.','Crumble feta on top, fold, and serve with toast.']::text[],array['high protein','low calorie']::text[]),
(pg_temp.sid('recipe:Banana protein pancakes'),'Banana protein pancakes','breakfast','Weekend pancakes that still fit your macros.',15,529,34.3,68.7,14.2,array['50 g oats, dry','118 g banana','100 g eggs, whole','15 g whey protein powder','10 g maple syrup']::text[],array['Blend oats, banana, eggs and whey into a batter.','Cook small pancakes in a non-stick pan, 2 minutes per side.','Serve with maple syrup.']::text[],array['high protein','sweet']::text[]),
(pg_temp.sid('recipe:Smoked salmon bagel'),'Smoked salmon bagel','breakfast','Omega-3s and protein in five minutes.',5,362,29.5,48.1,5.1,array['90 g bagel, plain','60 g cottage cheese, low fat','70 g smoked salmon','40 g cucumber']::text[],array['Toast the bagel.','Spread with cottage cheese.','Layer smoked salmon and sliced cucumber.']::text[],array['high protein','quick']::text[]),
(pg_temp.sid('recipe:Scrambled eggs on sourdough'),'Scrambled eggs on sourdough','breakfast','A classic with greens on the side.',10,466,28.3,42.0,20.9,array['150 g eggs, whole','70 g sourdough bread','5 g butter','40 g spinach','80 g tomato']::text[],array['Whisk eggs and scramble gently in butter.','Wilt spinach in the same pan.','Serve on toasted sourdough with sliced tomato.']::text[],array['vegetarian','quick']::text[]),
(pg_temp.sid('recipe:Chicken burrito bowl'),'Chicken burrito bowl','lunch','Meal-prep friendly and easy to scale.',15,686,61.3,77.9,14.5,array['150 g chicken breast, cooked','150 g white rice, cooked','80 g black beans, cooked','50 g sweetcorn','60 g tomato','50 g avocado','30 g mixed salad leaves']::text[],array['Slice the cooked chicken.','Build the bowl on rice with beans, corn, tomato and leaves.','Top with sliced avocado.']::text[],array['high protein','meal prep']::text[]),
(pg_temp.sid('recipe:Tuna and chickpea salad'),'Tuna and chickpea salad','lunch','No cooking, packs well for work.',10,542,47.7,42.9,20.9,array['120 g tuna, canned in water, drained','120 g chickpeas, cooked','80 g cucumber','80 g tomato','30 g onion','10 g olive oil','30 g feta']::text[],array['Drain the tuna and chickpeas.','Chop cucumber, tomato and onion.','Toss everything with olive oil and crumbled feta.']::text[],array['high protein','no cook']::text[]),
(pg_temp.sid('recipe:Turkey and hummus wrap'),'Turkey and hummus wrap','lunch','Lunch in five minutes.',5,417,39.7,41.8,10.1,array['62 g tortilla wrap','100 g turkey breast, cooked','40 g hummus','30 g spinach','50 g bell pepper']::text[],array['Spread hummus over the wrap.','Add turkey, spinach and sliced pepper.','Roll tightly and cut in half.']::text[],array['quick','high protein']::text[]),
(pg_temp.sid('recipe:Quinoa and halloumi salad'),'Quinoa and halloumi salad','lunch','Vegetarian lunch with a salty crunch.',15,464,21.5,40.0,25.2,array['150 g quinoa, cooked','60 g halloumi','40 g spinach','80 g tomato','60 g cucumber','7 g olive oil']::text[],array['Grill halloumi slices until golden.','Toss quinoa with spinach, tomato and cucumber.','Top with halloumi and drizzle with oil.']::text[],array['vegetarian']::text[]),
(pg_temp.sid('recipe:Prawn noodle stir-fry'),'Prawn noodle stir-fry','lunch','Quick wok dish with plenty of veg.',15,525,47.4,59.0,11.8,array['150 g prawns, cooked','180 g egg noodles, cooked','80 g broccoli','60 g bell pepper','50 g carrot','7 g olive oil']::text[],array['Stir-fry broccoli, pepper and carrot in oil for 3 minutes.','Add prawns and noodles, toss until hot.','Season with soy sauce and chilli to taste.']::text[],array['high protein','quick']::text[]),
(pg_temp.sid('recipe:Lentil and vegetable soup'),'Lentil and vegetable soup','lunch','Batch-cook for the week.',30,456,26.7,73.7,7.6,array['200 g lentils, cooked','80 g carrot','60 g onion','120 g chopped tomatoes, canned','40 g spinach','5 g olive oil','36 g wholemeal bread']::text[],array['Soften onion and carrot in oil.','Add tomatoes, lentils and stock, simmer 20 minutes.','Stir in spinach and serve with bread.']::text[],array['vegan','meal prep','high fibre']::text[]),
(pg_temp.sid('recipe:Salmon, sweet potato and greens'),'Salmon, sweet potato and greens','dinner','Balanced plate for recovery days.',25,547,37.6,48.0,22.6,array['140 g salmon fillet, cooked','200 g sweet potato, baked','100 g broccoli','5 g olive oil']::text[],array['Bake sweet potato wedges at 200C for 25 minutes.','Roast salmon for the last 12 minutes.','Steam broccoli and drizzle with oil.']::text[],array['high protein','omega-3']::text[]),
