(pg_temp.sid('recipe:Chicken thigh tray bake'),'Chicken thigh tray bake','dinner','One tray, minimal washing up.',40,670,52.9,51.9,27.3,array['180 g chicken thigh, cooked, skinless','200 g potato, boiled','80 g bell pepper','80 g courgette','50 g onion','7 g olive oil']::text[],array['Chop potatoes and veg, toss with oil and seasoning.','Add chicken thighs and roast at 200C for 35 minutes.']::text[],array['high protein','one pan']::text[]),
