(pg_temp.sid('recipe:Lemon cod with couscous'),'Lemon cod with couscous','dinner','Light and fresh, high protein.',20,491,52.9,52.0,7.4,array['180 g cod, cooked','150 g couscous, cooked','80 g peas, frozen','80 g green beans','5 g olive oil']::text[],array['Bake cod with lemon for 12 minutes.','Fluff couscous with peas.','Serve with green beans and a drizzle of oil.']::text[],array['high protein','low fat']::text[]),
